'use strict';

const {punct, copy} = require('./lexer');
const builtins = new Set(['__LINE__', '__FILE__', '__COUNTER__']);
const variadicError = '"__VA_ARGS__" can only appear in the expansion of a variadic macro';

class Macro {
  constructor(name, parameters, variadic, replacement, position, mainFile) {
    Object.assign(this, {name, parameters, variadic, replacement, position, mainFile});
    this.expanded = 0;
    this.tested = 0;
  }

  signature() {
    if (this.parameters === null) return this.name;
    const names = this.parameters.map(name => name === '__VA_ARGS__' ? '...' : name);
    return `${this.name}(${names.join(', ')})`;
  }
}

function checkName(operands, directive) {
  if (!operands.length) throw new Error(`no macro name given in #${directive} directive`);
  if (operands[0].kind !== 'identifier') throw new Error('macro names must be identifiers');
  const name = operands[0].spelling;
  if (name === 'defined') throw new Error('"defined" cannot be used as a macro name');
  if (builtins.has(name)) {
    const verb = directive === 'define' ? 'redefine' : 'undefine';
    throw new Error(`cannot ${verb} builtin macro "${name}"`);
  }
  return name;
}

function parseDefinition(operands, position, mainFile) {
  const name = checkName(operands, 'define');
  if (name === '__VA_ARGS__') throw new Error(variadicError);
  let index = 1;
  let parameters = null;
  let variadic = false;
  if (punct(operands[index], '(') && !operands[index].space) {
    parameters = [];
    index++;
    const requireToken = () => {
      if (!operands[index]) throw new Error("missing ')' in macro parameter list");
      return operands[index];
    };
    if (punct(requireToken(), ')')) index++;
    else {
      for (;;) {
        const token = requireToken();
        if (punct(token, '...')) {
          parameters.push('__VA_ARGS__');
          variadic = true;
        } else if (token.kind === 'identifier') {
          if (token.spelling === '__VA_ARGS__') throw new Error(variadicError);
          if (parameters.includes(token.spelling)) {
            throw new Error(`duplicate macro parameter "${token.spelling}"`);
          }
          parameters.push(token.spelling);
        } else throw new Error(`expected parameter name, found "${token.spelling}"`);
        index++;
        const separator = requireToken();
        index++;
        if (punct(separator, ')')) break;
        if (variadic) throw new Error(`expected ')' after "...", found "${separator.spelling}"`);
        if (!punct(separator, ',')) throw new Error(`expected ',' or ')', found "${separator.spelling}"`);
      }
    }
  }
  const replacement = operands.slice(index).map(copy);
  if (replacement.length) replacement[0].space = false;
  if (punct(replacement[0], '##') || punct(replacement.at(-1), '##')) {
    throw new Error("'##' cannot appear at either end of a macro expansion");
  }
  for (let item = 0; item < replacement.length; item++) {
    const token = replacement[item];
    if (!variadic && token.kind === 'identifier' && token.spelling === '__VA_ARGS__') {
      throw new Error(variadicError);
    }
    if (parameters !== null && punct(token, '#')
        && (replacement[item + 1]?.kind !== 'identifier'
          || !parameters.includes(replacement[item + 1].spelling))) {
      throw new Error("'#' is not followed by a macro parameter");
    }
  }
  return new Macro(name, parameters, variadic, replacement, {...position}, mainFile);
}

function identical(left, right) {
  if ((left.parameters === null) !== (right.parameters === null) || left.variadic !== right.variadic) return false;
  if (left.parameters !== null && (left.parameters.length !== right.parameters.length
      || left.parameters.some((name, index) => name !== right.parameters[index]))) return false;
  return left.replacement.length === right.replacement.length
    && left.replacement.every((token, index) => token.spelling === right.replacement[index].spelling
      && token.space === right.replacement[index].space);
}

module.exports = {builtins, checkName, parseDefinition, identical};

'use strict';

const {copy, punct, singleToken} = require('./lexer');
const {builtins} = require('./definitions');

function intersection(left, right) {
  return new Set([...left].filter(name => right.has(name)));
}

class Expander {
  constructor(table, diagnostic) {
    this.table = table;
    this.diagnostic = diagnostic;
    this.counter = 0;
    this.uses = new Map([...builtins].map(name => [name, 0]));
  }

  error(context, token, message) {
    this.diagnostic({file: context.displayName, line: token.line + context.offset}, 'error', message);
  }

  builtin(token, context) {
    this.uses.set(token.spelling, this.uses.get(token.spelling) + 1);
    let spelling;
    if (token.spelling === '__LINE__') spelling = String(token.line + context.offset);
    else if (token.spelling === '__FILE__') spelling = `"${context.displayName}"`;
    else spelling = String(this.counter++);
    return {kind: token.spelling === '__FILE__' ? 'string' : 'number', spelling,
      line: token.line, space: token.space, hide: new Set()};
  }

  collect(input, macro, token, context) {
    const argumentsList = [[]];
    const separators = [];
    let depth = 0;
    let closingIndex = -1;
    for (let index = input.length - 2; index >= 0; index--) {
      const current = input[index];
      if (depth === 0 && punct(current, ')')) {
        closingIndex = index;
        break;
      }
      if (depth === 0 && punct(current, ',')) {
        separators.push(copy(current));
        argumentsList.push([]);
      } else {
        if (punct(current, '(')) depth++;
        if (punct(current, ')')) depth--;
        argumentsList.at(-1).push(copy(current));
      }
    }
    let message;
    const count = argumentsList.length;
    const required = macro.parameters.length - Number(macro.variadic);
    if (closingIndex < 0) message = `unterminated argument list invoking macro "${macro.name}"`;
    else if (!macro.variadic && required === 0 && (count !== 1 || argumentsList[0].length)) {
      message = `macro "${macro.name}" passed ${count} arguments, but takes just 0`;
    } else if (count < required) {
      message = `macro "${macro.name}" requires ${required} arguments, but only ${count} given`;
    } else if (count > required && !macro.variadic) {
      message = `macro "${macro.name}" passed ${count} arguments, but takes just ${required}`;
    }
    if (message) {
      this.error(context, token, message);
      return null;
    }
    const raw = new Map();
    for (let index = 0; index < required; index++) raw.set(macro.parameters[index], argumentsList[index]);
    if (macro.variadic) {
      const rest = [];
      for (let index = required; index < argumentsList.length; index++) {
        if (index > required) rest.push(copy(separators[index - 1]));
        for (const item of argumentsList[index]) rest.push(copy(item));
      }
      raw.set('__VA_ARGS__', rest);
    }
    const closing = copy(input[closingIndex]);
    input.length = closingIndex;
    return {raw, closing};
  }

  stringize(raw, hash) {
    let spelling = '"';
    for (let index = 0; index < raw.length; index++) {
      const token = raw[index];
      if (index && token.space) spelling += ' ';
      spelling += token.kind === 'string' || token.kind === 'character'
        ? token.spelling.replaceAll('\\', '\\\\').replaceAll('"', '\\"') : token.spelling;
    }
    return {kind: 'string', spelling: spelling + '"', line: hash.line, space: hash.space, hide: new Set()};
  }

  paste(left, right, token, context) {
    if (left.kind === 'placemarker') return [{...copy(right), space: left.space}];
    if (right.kind === 'placemarker') return [copy(left)];
    const spelling = left.spelling + right.spelling;
    const kind = singleToken(spelling);
    if (kind) return [{kind, spelling, line: left.line, space: left.space,
      hide: intersection(left.hide, right.hide)}];
    this.error(context, token, `pasting "${left.spelling}" and "${right.spelling}" does not give a valid preprocessing token`);
    return [copy(left), {...copy(right), space: false}];
  }

  *substitute(macro, raw, token, hide, context) {
    const items = [];
    const expanded = new Map();
    const replacement = macro.replacement;
    for (let index = 0; index < replacement.length; index++) {
      const current = replacement[index];
      if (macro.parameters !== null && punct(current, '#')) {
        items.push([this.stringize(raw.get(replacement[++index].spelling), current)]);
      } else if (punct(current, '##')) items.push({paste: copy(current)});
      else if (current.kind === 'identifier' && raw.has(current.spelling)) {
        const name = current.spelling;
        let argument;
        if (punct(replacement[index - 1], '##') || punct(replacement[index + 1], '##')) {
          argument = raw.get(name);
        } else {
          if (!expanded.has(name)) expanded.set(name, yield this.scan(raw.get(name), context));
          argument = expanded.get(name);
        }
        const sequence = argument.map(copy);
        if (sequence.length) sequence[0].space = current.space;
        else sequence.push({kind: 'placemarker', spelling: '', line: current.line,
          space: current.space, hide: new Set()});
        items.push(sequence);
      } else items.push([copy(current)]);
    }
    const joined = [];
    for (let index = 0; index < items.length; index++) {
      const item = items[index];
      if (!item.paste) {
        for (const current of item) joined.push(copy(current));
      } else {
        const left = joined.pop();
        const next = items[++index];
        const right = next.paste ? [copy(next.paste)] : next;
        for (const current of this.paste(left, right[0], token, context)) joined.push(current);
        for (let offset = 1; offset < right.length; offset++) joined.push(copy(right[offset]));
      }
    }
    const result = [];
    let separated = false;
    for (const current of joined) {
      if (current.kind === 'placemarker') separated ||= current.space;
      else {
        const next = copy(current);
        next.line = token.line;
        next.space ||= separated;
        for (const name of hide) next.hide.add(name);
        result.push(next);
        separated = false;
      }
    }
    if (result.length) result[0].space = token.space;
    return result;
  }

  *scan(sequence, context) {
    const input = sequence.map(copy).reverse();
    const result = [];
    while (input.length) {
      const token = input.pop();
      if (token.kind !== 'identifier' || token.hide.has(token.spelling)) {
        result.push(token);
        continue;
      }
      if (builtins.has(token.spelling)) {
        result.push(this.builtin(token, context));
        continue;
      }
      const macro = this.table.get(token.spelling);
      if (!macro || macro.parameters !== null && !punct(input.at(-1), '(')) {
        result.push(token);
        continue;
      }
      let hide = new Set(token.hide);
      let raw = new Map();
      if (macro.parameters !== null) {
        const collected = this.collect(input, macro, token, context);
        if (!collected) {
          result.push(token);
          continue;
        }
        raw = collected.raw;
        hide = intersection(token.hide, collected.closing.hide);
      }
      hide.add(macro.name);
      const replacement = yield this.substitute(macro, raw, token, hide, context);
      macro.expanded++;
      if (!replacement.length && token.space && input.length) input.at(-1).space = true;
      for (let index = replacement.length - 1; index >= 0; index--) input.push(replacement[index]);
    }
    return result;
  }

  expand(tokens, context) {
    const stack = [this.scan(tokens, context)];
    let value;
    while (stack.length) {
      const step = stack.at(-1).next(value);
      if (step.done) {
        stack.pop();
        value = step.value;
      } else {
        stack.push(step.value);
        value = undefined;
      }
    }
    return value;
  }
}

module.exports = {Expander};

'use strict';

const {punct} = require('./lexer');
const precedence = new Map([
  ['||', 1], ['&&', 2], ['|', 3], ['^', 4], ['&', 5], ['==', 6], ['!=', 6],
  ['<', 7], ['>', 7], ['<=', 7], ['>=', 7], ['<<', 8], ['>>', 8],
  ['+', 9], ['-', 9], ['*', 10], ['/', 10], ['%', 10],
]);

function complete(generator) {
  const stack = [generator];
  let value;
  while (stack.length) {
    const step = stack.at(-1).next(value);
    if (step.done) {
      stack.pop();
      value = step.value;
    } else {
      stack.push(step.value);
      value = undefined;
    }
  }
  return value;
}

function integerConstant(spelling) {
  let digits = spelling;
  for (const suffix of ['ll', 'LL', 'l', 'L']) {
    if (digits.length > suffix.length && digits.endsWith(suffix)) {
      digits = digits.slice(0, -suffix.length);
      break;
    }
  }
  if (/^0[xX][0-9a-fA-F]+$/.test(digits)) return Number(digits);
  if (/^0[0-7]*$/.test(digits)) return Number.parseInt(digits, 8);
  if (/^[1-9][0-9]*$/.test(digits)) return Number(digits);
  throw new Error(`invalid integer constant "${spelling}"`);
}

function characterConstant(spelling) {
  const body = spelling.slice(1, -1);
  if (body.length === 1 && body !== "'" && body !== '\\') return body.charCodeAt(0);
  const escapes = new Map([['n', 10], ['t', 9], ['\\', 92], ["'", 39], ['"', 34], ['0', 0]]);
  if (body.length === 2 && body[0] === '\\' && escapes.has(body[1])) return escapes.get(body[1]);
  throw new Error(`invalid character constant ${spelling}`);
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens;
    this.index = 0;
  }

  *expression() {
    const condition = yield this.binary(1);
    if (!punct(this.tokens[this.index], '?')) return condition;
    this.index++;
    const yes = yield this.expression();
    if (!punct(this.tokens[this.index], ':')) throw new Error("'?' without following ':'");
    this.index++;
    const no = yield this.expression();
    return {kind: 'conditional', condition, yes, no};
  }

  *binary(minimum) {
    let left = yield this.unary();
    for (;;) {
      const token = this.tokens[this.index];
      const level = token?.kind === 'punctuator' ? precedence.get(token.spelling) : undefined;
      if (level === undefined || level < minimum) return left;
      this.index++;
      const right = yield this.binary(level + 1);
      left = {kind: 'binary', operator: token.spelling, left, right};
    }
  }

  *unary() {
    const token = this.tokens[this.index];
    if (!token) throw new Error('expected value at end of expression');
    this.index++;
    if (token.kind === 'punctuator' && ['+', '-', '!', '~'].includes(token.spelling)) {
      const operand = yield this.unary();
      return {kind: 'unary', operator: token.spelling, operand};
    }
    if (token.kind === 'number') return {kind: 'constant', value: integerConstant(token.spelling)};
    if (token.kind === 'character') return {kind: 'constant', value: characterConstant(token.spelling)};
    if (token.kind === 'identifier') return {kind: 'identifier', name: token.spelling};
    if (punct(token, '(')) {
      const inside = yield this.expression();
      if (!punct(this.tokens[this.index], ')')) throw new Error("missing ')' in expression");
      this.index++;
      return inside;
    }
    throw new Error(`expected value before "${token.spelling}"`);
  }

  parse() {
    const tree = complete(this.expression());
    if (this.index < this.tokens.length) {
      throw new Error(`missing binary operator before "${this.tokens[this.index].spelling}"`);
    }
    return tree;
  }
}

function *evaluate(tree, warning) {
  if (tree.kind === 'constant') return tree.value;
  if (tree.kind === 'identifier') {
    warning(`identifier "${tree.name}" evaluates to 0`);
    return 0;
  }
  if (tree.kind === 'conditional') {
    const value = yield evaluate(tree.condition, warning);
    return yield evaluate(value !== 0 ? tree.yes : tree.no, warning);
  }
  if (tree.kind === 'unary') {
    const value = yield evaluate(tree.operand, warning);
    switch (tree.operator) {
      case '+': return value;
      case '-': return -value;
      case '!': return Number(value === 0);
      case '~': return -value - 1;
    }
  }
  const left = yield evaluate(tree.left, warning);
  if (tree.operator === '&&' && left === 0) return 0;
  if (tree.operator === '||' && left !== 0) return 1;
  const right = yield evaluate(tree.right, warning);
  switch (tree.operator) {
    case '&&': case '||': return Number(right !== 0);
    case '*': return left * right;
    case '+': return left + right;
    case '-': return left - right;
    case '/': case '%': {
      if (right === 0) throw new Error('division by zero in #if');
      const quotient = Number(BigInt(left) / BigInt(right));
      return tree.operator === '/' ? quotient : left - right * quotient;
    }
    case '<<': return left * 2 ** right;
    case '>>': return Math.floor(left / 2 ** right);
    case '&': return left & right;
    case '|': return left | right;
    case '^': return left ^ right;
    case '==': return Number(left === right);
    case '!=': return Number(left !== right);
    case '<': return Number(left < right);
    case '>': return Number(left > right);
    case '<=': return Number(left <= right);
    case '>=': return Number(left >= right);
  }
}

function expressionValue(tokens, warning) {
  return complete(evaluate(new Parser(tokens).parse(), warning));
}

module.exports = {expressionValue};

'use strict';

const fs = require('node:fs');
const {lexFile, punct} = require('./lexer');

function findGuard(logicalLines) {
  const lines = logicalLines.filter(line => line.tokens.length);
  if (!lines.length) return null;
  const first = lines[0].tokens;
  const last = lines.at(-1).tokens;
  if (first.length !== 3 || !punct(first[0], '#') || first[1].spelling !== 'ifndef'
      || first[2].kind !== 'identifier' || last.length !== 2
      || !punct(last[0], '#') || last[1].spelling !== 'endif') return null;
  let depth = 0;
  for (let index = 0; index < lines.length; index++) {
    const name = lines[index].name;
    if (['if', 'ifdef', 'ifndef'].includes(name)) depth++;
    else if (['elif', 'elifdef', 'elifndef', 'else'].includes(name) && depth === 1) return null;
    else if (name === 'endif') {
      depth--;
      if (depth === 0 && index !== lines.length - 1) return null;
    }
  }
  return depth === 0 ? first[2].spelling : null;
}

class IncludeManager {
  constructor() {
    this.files = new Map();
    this.order = [];
  }

  search(name, quoted) {
    const candidates = quoted ? [name, `include/${name}`] : [`include/${name}`];
    for (const path of candidates) {
      if (fs.existsSync(`input/${path}`)) return path;
    }
    return null;
  }

  enter(path) {
    if (!this.files.has(path)) {
      const lexical = lexFile(fs.readFileSync(`input/${path}`, 'utf8'));
      this.files.set(path, {path, lines: lexical.lines, physicalLines: lexical.physicalLines,
        guard: findGuard(lexical.lines), once: false, entered: 0, skipped: 0,
        outputLines: 0, skippedLines: 0});
      this.order.push(path);
    }
    const file = this.files.get(path);
    file.entered++;
    return file;
  }
}

module.exports = {IncludeManager};

'use strict';

const punctuators = new Set([
  '...', '<<=', '>>=', '->', '++', '--', '<<', '>>', '<=', '>=', '==', '!=',
  '&&', '||', '*=', '/=', '%=', '+=', '-=', '&=', '^=', '|=', '##',
  '[', ']', '(', ')', '{', '}', '.', '&', '*', '+', '-', '~', '!', '/', '%',
  '<', '>', '^', '|', '?', ':', ';', '=', ',', '#',
]);

function punct(token, spelling) {
  return token?.kind === 'punctuator' && token.spelling === spelling;
}

function copy(token) {
  return {...token, hide: new Set(token.hide)};
}

function readBasic(source, start = 0) {
  const first = source[start];
  if (first === undefined) return null;
  let end = start + 1;
  let kind;
  if (/[A-Za-z_]/.test(first)) {
    while (/[A-Za-z0-9_]/.test(source[end] ?? '')) end++;
    kind = 'identifier';
  } else if (/[0-9]/.test(first) || first === '.' && /[0-9]/.test(source[end] ?? '')) {
    while (end < source.length) {
      if (/[eEpP]/.test(source[end]) && /[+-]/.test(source[end + 1] ?? '')) end += 2;
      else if (/[A-Za-z0-9_.]/.test(source[end])) end++;
      else break;
    }
    kind = 'number';
  } else if (first === "'" || first === '"') {
    let cursor = end;
    while (cursor < source.length && source[cursor] !== '\n') {
      if (source[cursor] === first) {
        end = cursor + 1;
        kind = first === "'" ? 'character' : 'string';
        break;
      }
      if (source[cursor] === '\\' && source[cursor + 1] !== '\n') cursor += 2;
      else cursor++;
    }
  }
  if (!kind) {
    kind = 'other';
    for (const length of [3, 2, 1]) {
      const spelling = source.slice(start, start + length);
      if (spelling.length === length && punctuators.has(spelling)) {
        end = start + length;
        kind = 'punctuator';
        break;
      }
    }
  }
  return {kind, spelling: source.slice(start, end), length: end - start};
}

function scan(source, physical) {
  const lines = [];
  let tokens = [];
  let startLine = 1;
  let separated = true;
  for (let index = 0; index < source.length;) {
    if (source[index] === ' ') {
      separated = true;
      index++;
    } else if (source[index] === '\n') {
      const endLine = physical[index++];
      const name = punct(tokens[0], '#') && tokens[1]?.kind === 'identifier'
        ? tokens[1].spelling : null;
      lines.push({tokens, startLine, endLine, name});
      tokens = [];
      startLine = endLine + 1;
      separated = true;
    } else if (source.startsWith('/*', index)) {
      const closing = source.indexOf('*/', index + 2);
      index = closing < 0 ? source.length : closing + 2;
      separated = true;
    } else if (source.startsWith('//', index)) {
      const end = source.indexOf('\n', index + 2);
      index = end < 0 ? source.length : end;
      separated = true;
    } else {
      let read;
      if (tokens.length === 2 && tokens[0].spelling === '#'
          && tokens[1].spelling === 'include' && source[index] === '<') {
        const closing = source.indexOf('>', index + 1);
        const newline = source.indexOf('\n', index + 1);
        if (closing >= 0 && (newline < 0 || closing < newline)) {
          read = {kind: 'header', spelling: source.slice(index, closing + 1), length: closing + 1 - index};
        }
      }
      read ??= readBasic(source, index);
      tokens.push({kind: read.kind, spelling: read.spelling, line: physical[index],
        space: separated, hide: new Set()});
      index += read.length;
      separated = false;
    }
  }
  return {lines, remainder: tokens};
}

function lexFile(text) {
  const characters = [];
  const physical = [];
  let line = 1;
  for (let index = 0; index < text.length; index++) {
    if (text[index] === '\\' && text[index + 1] === '\n') {
      index++;
      line++;
    } else {
      characters.push(text[index]);
      physical.push(line);
      if (text[index] === '\n') line++;
    }
  }
  return {lines: scan(characters.join(''), physical).lines, physicalLines: line - 1};
}

function lexDefinition(text) {
  return scan(text, Array(text.length).fill(1)).remainder;
}

function render(tokens) {
  let result = '';
  for (let index = 0; index < tokens.length; index++) {
    if (index && tokens[index].space) result += ' ';
    result += tokens[index].spelling;
  }
  return result;
}

function singleToken(text) {
  if (text.startsWith('//') || text.startsWith('/*')) return null;
  const token = readBasic(text);
  return token?.length === text.length ? token.kind : null;
}

module.exports = {punct, copy, readBasic, lexFile, lexDefinition, render, singleToken};

'use strict';

const fs = require('node:fs');
const {punct, copy, readBasic, lexDefinition, render} = require('./lexer');
const {builtins, checkName, parseDefinition, identical} = require('./definitions');
const {expressionValue} = require('./expression');
const {Expander} = require('./expander');
const {IncludeManager} = require('./include_manager');

const starts = new Set(['if', 'ifdef', 'ifndef']);
const conditionals = new Set([...starts, 'elif', 'elifdef', 'elifndef', 'else', 'endif']);
const resultKinds = [['taken', 'taken'], ['not taken', 'not_taken'], ['skipped', 'skipped'],
  ['not evaluated', 'not_evaluated'], ['closes', 'endif']];

class Preprocessor {
  constructor() {
    this.table = new Map();
    this.everDefined = new Set();
    this.poisoned = new Set();
    this.saved = new Map();
    this.history = [];
    this.diagnostics = [];
    this.diagnosticCounts = {error: 0, warning: 0};
    this.output = [];
    this.previous = null;
    this.tree = [];
    this.records = [];
    this.regions = [];
    this.recordCounts = {taken: 0, not_taken: 0, skipped: 0, not_evaluated: 0, endif: 0};
    this.includes = new IncludeManager();
    this.expander = new Expander(this.table, (position, kind, message) => this.diagnostic(position, kind, message));
  }

  position(context, physicalLine) {
    return {file: context.displayName, line: physicalLine + context.offset};
  }

  diagnostic(position, kind, message) {
    this.diagnostics.push(`${position.file}:${position.line}: ${kind}: ${message}`);
    this.diagnosticCounts[kind]++;
  }

  recordHistory(position, content) {
    this.history.push(`${position.file}:${position.line}: ${content}`);
  }

  unused(macro) {
    if (macro.mainFile && macro.expanded === 0 && macro.tested === 0) {
      this.diagnostic(macro.position, 'warning', `macro "${macro.name}" is not used`);
    }
  }

  define(operands, position, mainFile) {
    const macro = parseDefinition(operands, position, mainFile);
    const old = this.table.get(macro.name);
    if (old && identical(old, macro)) {
      this.recordHistory(position, `identical ${macro.signature()}`);
      return;
    }
    if (old) {
      this.unused(old);
      this.diagnostic(position, 'warning', `"${macro.name}" redefined (previous definition at ${old.position.file}:${old.position.line})`);
    }
    this.table.set(macro.name, macro);
    this.everDefined.add(macro.name);
    this.recordHistory(position, `${old ? 'redefine' : 'define'} ${macro.signature()}`);
  }

  undefine(operands, position) {
    const name = checkName(operands, 'undef');
    if (operands.length > 1) this.diagnostic(position, 'warning', 'extra tokens at end of #undef directive');
    const old = this.table.get(name);
    if (old) {
      this.unused(old);
      this.table.delete(name);
    }
    this.recordHistory(position, `undef ${name}${old ? '' : ' (not defined)'}`);
  }

  defined(name) {
    const macro = this.table.get(name);
    if (macro) {
      macro.tested++;
      return true;
    }
    return builtins.has(name) || name === '__has_include';
  }

  poison(tokens, context) {
    for (const token of tokens) {
      if (token.kind === 'identifier' && this.poisoned.has(token.spelling)) {
        this.diagnostic(this.position(context, token.line), 'error', `attempt to use poisoned "${token.spelling}"`);
      }
    }
  }

  separator(left, right) {
    return left === '/' && (right[0] === '/' || right[0] === '*')
      || readBasic(left + right).length !== left.length;
  }

  outputRendering(tokens) {
    let text = '';
    for (let index = 0; index < tokens.length; index++) {
      const token = tokens[index];
      if (index && (token.space || this.separator(tokens[index - 1].spelling, token.spelling))) text += ' ';
      text += token.spelling;
    }
    return text;
  }

  marker(file, line, flag = '') {
    this.output.push(`# ${line} "${file}"${flag ? ` ${flag}` : ''}`);
    this.previous = {file, line: line - 1};
  }

  outputLine(context, physicalLine, text) {
    const position = this.position(context, physicalLine);
    if (this.previous.file === position.file && this.previous.line < position.line
        && position.line <= this.previous.line + 8) {
      for (let line = this.previous.line + 1; line < position.line; line++) this.output.push('');
    } else this.marker(position.file, position.line);
    this.output.push(text);
    this.previous = position;
    context.file.outputLines++;
  }

  flush(context) {
    this.poison(context.segment, context);
    const tokens = this.expander.expand(context.segment, context);
    context.segment = [];
    for (let start = 0; start < tokens.length;) {
      let end = start + 1;
      while (end < tokens.length && tokens[end].line === tokens[start].line) end++;
      this.outputLine(context, tokens[start].line, this.outputRendering(tokens.slice(start, end)));
      start = end;
    }
  }

  header(tokens, index = 0) {
    const token = tokens[index];
    let rendering;
    let end;
    if (token?.kind === 'string' || token?.kind === 'header') {
      rendering = token.spelling;
      end = index + 1;
    } else if (punct(token, '<')) {
      end = index + 1;
      while (end < tokens.length && !punct(tokens[end], '>')) end++;
      if (end === tokens.length) throw new Error('missing terminating > character');
      rendering = '<' + render(tokens.slice(index + 1, end)) + '>';
      end++;
    } else return null;
    return {rendering, end, name: rendering.slice(1, -1), quoted: rendering[0] === '"'};
  }

  replaceOperators(operands) {
    const result = [];
    for (let index = 0; index < operands.length; index++) {
      const token = operands[index];
      if (token.kind !== 'identifier' || !['defined', '__has_include'].includes(token.spelling)) {
        result.push(copy(token));
        continue;
      }
      let value;
      if (token.spelling === 'defined') {
        index++;
        const parenthesized = punct(operands[index], '(');
        if (parenthesized) index++;
        if (operands[index]?.kind !== 'identifier') throw new Error('operator "defined" requires an identifier');
        const name = operands[index].spelling;
        if (parenthesized && !punct(operands[++index], ')')) throw new Error('missing \')\' after "defined"');
        value = this.defined(name);
      } else {
        if (!punct(operands[++index], '(')) throw new Error('missing \'(\' after "__has_include"');
        const header = this.header(operands, index + 1);
        if (!header || !header.name) throw new Error('operator "__has_include" requires a header-name');
        index = header.end;
        if (!punct(operands[index], ')')) throw new Error('missing \')\' after "__has_include" operand');
        value = this.includes.search(header.name, header.quoted) !== null;
      }
      result.push({kind: 'number', spelling: value ? '1' : '0', line: token.line,
        space: token.space, hide: new Set()});
    }
    return result;
  }

  testCondition(context, logical) {
    const operands = logical.tokens.slice(2);
    const position = this.position(context, logical.tokens[0].line);
    this.poison(operands, context);
    let value = null;
    let expanded = null;
    const expression = logical.name === 'if' || logical.name === 'elif';
    try {
      if (expression) {
        const replaced = this.replaceOperators(operands);
        expanded = this.expander.expand(replaced, context);
        if (!expanded.length) throw new Error(`#${logical.name} with no expression`);
        value = expressionValue(expanded, message => this.diagnostic(position, 'warning', message));
      } else {
        if (!operands.length) throw new Error(`no macro name given in #${logical.name} directive`);
        if (operands[0].kind !== 'identifier') throw new Error('macro names must be identifiers');
        if (operands.length > 1) this.diagnostic(position, 'warning', `extra tokens at end of #${logical.name} directive`);
        value = Number(this.defined(operands[0].spelling));
        if (logical.name === 'ifndef' || logical.name === 'elifndef') value = 1 - value;
      }
    } catch (error) {
      this.diagnostic(position, 'error', error.message);
      value = null;
    }
    let description = value === null ? 'not taken (error)' : value !== 0 ? 'taken' : 'not taken';
    if (expression && value !== null) description += ` (value ${value})`;
    if (expanded !== null) description += ` [${this.outputRendering(expanded)}]`;
    return {taken: value !== null && value !== 0, description};
  }

  recordConditional(context, logical, depth, result) {
    const position = this.position(context, logical.tokens[0].line);
    const operands = logical.tokens.slice(2);
    const directive = `#${logical.name}${operands.length ? ` ${render(operands)}` : ''}`;
    this.records.push(`${position.file}:${position.line}: ${' '.repeat(2 * depth)}${directive} => ${result}`);
    for (const [prefix, key] of resultKinds) {
      if (result.startsWith(prefix)) {
        this.recordCounts[key]++;
        break;
      }
    }
  }

  closeSkipped(context, block, end) {
    const start = block.skipStart;
    if (start !== null && end >= start) {
      const count = end - start + 1;
      this.regions.push(`${context.displayName}:${start + context.offset}-${end + context.offset} lines=${count}`);
      context.file.skippedLines += count;
    }
    block.skipStart = null;
  }

  conditional(context, logical) {
    const stack = context.conditions;
    const position = this.position(context, logical.tokens[0].line);
    if (starts.has(logical.name)) {
      const block = {kind: logical.name, start: position, parentActive: !stack.length || stack.at(-1).active,
        chosen: false, active: false, elseSeen: false, skipStart: null};
      let result = 'skipped';
      if (block.parentActive) {
        const test = this.testCondition(context, logical);
        result = test.description;
        block.active = block.chosen = test.taken;
        if (!block.active) block.skipStart = logical.endLine + 1;
      }
      this.recordConditional(context, logical, stack.length, result);
      stack.push(block);
      return;
    }
    if (!stack.length) {
      this.diagnostic(position, 'error', `#${logical.name} without #if`);
      return;
    }
    const depth = stack.length - 1;
    const block = stack.at(-1);
    this.closeSkipped(context, block, logical.startLine - 1);
    let result;
    if (logical.name === 'endif') {
      stack.pop();
      if (block.parentActive && logical.tokens.length > 2) {
        this.diagnostic(position, 'warning', 'extra tokens at end of #endif directive');
      }
      result = `closes #${block.kind} at line ${block.start.line}`;
    } else {
      if (block.elseSeen) this.diagnostic(position, 'error', `#${logical.name} after #else`);
      if (logical.name === 'else') {
        if (block.parentActive && logical.tokens.length > 2) {
          this.diagnostic(position, 'warning', 'extra tokens at end of #else directive');
        }
        block.elseSeen = true;
        if (block.parentActive) {
          block.active = !block.chosen;
          block.chosen = true;
          result = block.active ? 'taken' : 'not taken';
        } else result = 'skipped';
      } else if (!block.parentActive) {
        block.active = false;
        result = 'skipped';
      } else if (block.chosen) {
        block.active = false;
        result = 'not evaluated';
      } else {
        const test = this.testCondition(context, logical);
        block.active = test.taken;
        if (test.taken) block.chosen = true;
        result = test.description;
      }
      if (block.parentActive && !block.active) block.skipStart = logical.endLine + 1;
    }
    this.recordConditional(context, logical, depth, result);
  }

  include(context, logical, operands, position) {
    let tokens = operands;
    let header = this.header(tokens);
    if (!header && tokens.length) {
      tokens = this.expander.expand(tokens, context);
      header = this.header(tokens);
    }
    if (!header) throw new Error('#include expects "FILENAME" or <FILENAME>');
    if (tokens.length > header.end) this.diagnostic(position, 'warning', 'extra tokens at end of #include directive');
    if (!header.name) throw new Error('empty filename in #include');
    const path = this.includes.search(header.name, header.quoted);
    const prefix = `${' '.repeat(2 * (context.depth + 1))}${logical.tokens[0].line}: `;
    if (path === null) {
      this.tree.push(`${prefix}${header.rendering} [not found]`);
      this.diagnostic(position, 'error', `cannot find include file ${header.rendering}`);
      return;
    }
    const file = this.includes.files.get(path);
    if (file && (file.once || file.guard && this.table.has(file.guard))) {
      this.tree.push(`${prefix}${path} [skipped: ${file.once ? 'pragma once' : `guard ${file.guard}`}]`);
      file.skipped++;
      return;
    }
    if (context.depth + 1 > 8) {
      this.tree.push(`${prefix}${path} [too deep]`);
      this.diagnostic(position, 'error', '#include nested too deeply');
      return;
    }
    this.tree.push(prefix + path);
    this.marker(path, 1, '1');
    this.processFile(path, context.depth + 1);
    this.marker(context.displayName, logical.endLine + 1 + context.offset, '2');
  }

  lineDirective(context, logical, operands) {
    const decimal = token => token?.kind === 'number' && /^[0-9]+$/.test(token.spelling);
    if (!decimal(operands[0])) operands = this.expander.expand(operands, context);
    if (operands.length < 1 || operands.length > 2 || !decimal(operands[0])
        || operands.length === 2 && operands[1].kind !== 'string') throw new Error('invalid #line directive');
    const line = Number(operands[0].spelling);
    if (line < 1 || line > 2147483647) throw new Error('line number out of range');
    context.offset = line - (logical.endLine + 1);
    if (operands.length === 2) context.displayName = operands[1].spelling.slice(1, -1);
  }

  pragma(context, logical, operands, position) {
    const first = operands[0];
    if (first?.kind === 'identifier' && first.spelling === 'once') {
      if (operands.length > 1) this.diagnostic(position, 'warning', 'extra tokens at end of #pragma once directive');
      if (context.depth === 0) this.diagnostic(position, 'warning', '#pragma once in main file');
      context.file.once = true;
    } else if (first?.spelling === 'GCC' && operands[1]?.spelling === 'poison') {
      if (operands.slice(2).some(token => token.kind !== 'identifier')) throw new Error('invalid #pragma GCC poison directive');
      for (const token of operands.slice(2)) {
        if (this.table.has(token.spelling)) this.diagnostic(position, 'warning', `poisoning existing macro "${token.spelling}"`);
        this.poisoned.add(token.spelling);
      }
    } else if (first?.kind === 'identifier' && ['push_macro', 'pop_macro'].includes(first.spelling)) {
      if (operands.length !== 4 || !punct(operands[1], '(') || operands[2].kind !== 'string'
          || !punct(operands[3], ')')) throw new Error(`invalid #pragma ${first.spelling} directive`);
      const name = operands[2].spelling.slice(1, -1);
      if (!this.saved.has(name)) this.saved.set(name, []);
      const stack = this.saved.get(name);
      if (first.spelling === 'push_macro') {
        stack.push(this.table.get(name) ?? null);
        this.recordHistory(position, `push ${name}`);
      } else if (!stack.length) this.diagnostic(position, 'warning', `no matching push_macro for "${name}"`);
      else {
        const macro = stack.pop();
        if (macro) this.table.set(name, macro);
        else this.table.delete(name);
        this.recordHistory(position, `pop ${name}${macro ? '' : ' (undefined)'}`);
      }
    } else this.outputLine(context, logical.tokens[0].line, `#pragma${operands.length ? ` ${render(operands)}` : ''}`);
  }

  directive(context, logical) {
    if (logical.tokens.length === 1) return;
    const operands = logical.tokens.slice(2);
    const position = this.position(context, logical.tokens[0].line);
    if (!(logical.name === 'pragma' && operands[0]?.spelling === 'GCC' && operands[1]?.spelling === 'poison')) {
      this.poison(operands, context);
    }
    try {
      switch (logical.name) {
        case 'define': this.define(operands, position, context.depth === 0); break;
        case 'undef': this.undefine(operands, position); break;
        case 'include': this.include(context, logical, operands, position); break;
        case 'line': this.lineDirective(context, logical, operands); break;
        case 'error': case 'warning':
          this.diagnostic(position, logical.name, `#${logical.name}${operands.length ? ` ${render(operands)}` : ''}`);
          break;
        case 'pragma': this.pragma(context, logical, operands, position); break;
        default: this.diagnostic(position, 'error', `invalid preprocessing directive #${logical.tokens[1].spelling}`);
      }
    } catch (error) {
      this.diagnostic(position, 'error', error.message);
    }
  }

  processFile(path, depth) {
    const file = this.includes.enter(path);
    const context = {file, depth, displayName: path, offset: 0, conditions: [], segment: []};
    for (const logical of file.lines) {
      if (conditionals.has(logical.name)) {
        this.flush(context);
        this.conditional(context, logical);
      } else if (context.conditions.length && !context.conditions.at(-1).active) continue;
      else if (punct(logical.tokens[0], '#')) {
        this.flush(context);
        this.directive(context, logical);
      } else {
        for (const token of logical.tokens) context.segment.push(copy(token));
      }
    }
    this.flush(context);
    for (const block of context.conditions) this.closeSkipped(context, block, file.physicalLines);
    for (const block of context.conditions) this.diagnostic(block.start, 'error', `unterminated #${block.kind}`);
  }

  dependencies() {
    const lines = [];
    let current = 'main.o:';
    let hasPath = false;
    for (const path of this.includes.order) {
      if (current.length + 1 + path.length > 76 && hasPath) {
        lines.push(current + ' \\');
        current = ' ';
        hasPath = false;
      }
      current += ' ' + path;
      hasPath = true;
    }
    lines.push(current);
    return lines;
  }

  includeReport() {
    const lines = ['main.c', ...this.tree, '', '== files =='];
    for (const path of [...this.includes.files.keys()].sort()) {
      const file = this.includes.files.get(path);
      lines.push(`${path} entered=${file.entered} skipped=${file.skipped} lines=${file.physicalLines}`
        + ` output_lines=${file.outputLines} skipped_lines=${file.skippedLines} guard=${file.guard ?? '-'} once=${file.once ? 'yes' : 'no'}`);
    }
    return [...lines, '', ...this.dependencies()];
  }

  macroReport() {
    const names = [...this.table.keys()].sort();
    const references = new Map();
    for (const name of names) {
      const macro = this.table.get(name);
      const found = new Set();
      for (const token of macro.replacement) {
        if (token.kind === 'identifier' && this.table.has(token.spelling)
            && !macro.parameters?.includes(token.spelling)) found.add(token.spelling);
      }
      references.set(name, [...found].sort());
    }
    const recursive = name => {
      const pending = [...references.get(name)];
      const seen = new Set();
      while (pending.length) {
        const current = pending.pop();
        if (current === name) return true;
        if (seen.has(current)) continue;
        seen.add(current);
        for (const next of references.get(current)) pending.push(next);
      }
      return false;
    };
    const lines = ['== history ==', ...this.history, '', '== table =='];
    let objectLike = 0;
    for (const name of names) {
      const macro = this.table.get(name);
      if (macro.parameters === null) objectLike++;
      lines.push(`#define ${macro.signature()}${macro.replacement.length ? ` ${render(macro.replacement)}` : ''}`);
      lines.push(`  at ${macro.position.file}:${macro.position.line} expanded=${macro.expanded} tested=${macro.tested} recursive=${recursive(name) ? 'yes' : 'no'}`);
      lines.push(['  refs:', ...references.get(name)].join(' '));
    }
    const undefinedNames = [...this.everDefined].filter(name => !this.table.has(name)).sort();
    lines.push('', `macros=${names.length} object_like=${objectLike} function_like=${names.length - objectLike}`);
    lines.push(['undefined:', ...undefinedNames].join(' '));
    const uses = this.expander.uses;
    lines.push(`builtins: __COUNTER__=${uses.get('__COUNTER__')} __FILE__=${uses.get('__FILE__')} __LINE__=${uses.get('__LINE__')}`);
    return lines;
  }

  conditionalReport() {
    const count = this.recordCounts;
    const totals = `directives=${this.records.length} taken=${count.taken} not_taken=${count.not_taken}`
      + ` skipped=${count.skipped} not_evaluated=${count.not_evaluated} endif=${count.endif} regions=${this.regions.length}`;
    return [...this.records, '', '== skipped regions ==', ...this.regions, '', totals];
  }

  run() {
    const lines = fs.readFileSync('input/defines.txt', 'utf8').split('\n');
    for (let index = 0; index < lines.length; index++) {
      if (lines[index] === '') continue;
      const equal = lines[index].indexOf('=');
      const text = equal < 0 ? lines[index] + ' 1'
        : lines[index].slice(0, equal) + ' ' + lines[index].slice(equal + 1);
      const position = {file: 'defines.txt', line: index + 1};
      try {
        this.define(lexDefinition(text), position, false);
      } catch (error) {
        this.diagnostic(position, 'error', error.message);
      }
    }
    this.marker('main.c', 1);
    this.processFile('main.c', 0);
    for (const name of [...this.table.keys()].sort()) this.unused(this.table.get(name));
    const counts = this.diagnosticCounts;
    const reports = new Map([
      ['preprocessed.txt', this.output], ['includes.txt', this.includeReport()],
      ['macros.txt', this.macroReport()], ['conditionals.txt', this.conditionalReport()],
      ['diagnostics.txt', [...this.diagnostics, `errors=${counts.error} warnings=${counts.warning}`]],
    ]);
    fs.mkdirSync('output', {recursive: true});
    for (const [name, content] of reports) fs.writeFileSync(`output/${name}`, content.join('\n') + '\n');
  }
}

new Preprocessor().run();
